mapper.select:
SELECT ap.*, ac.`name`, ap.project_id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', ap.monomer_id 'monomer.id', m.name 'monomer.name', ap.area_id 'area.id', a.`name` 'area.name' FROM `tech_auxiliary_part` ap INNER JOIN sys_auxiliary_classification ac ON ap.auxiliary_class_id = ac.id AND ac.bool_delete_enum = 0 LEFT JOIN contract_project cp on ap.project_id = cp.id and cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m on ap.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN plan_area a on ap.area_id = a.id AND a.bool_delete_enum = 0 WHERE ap.bool_delete_enum = 0
and ap.project_id = #{projectId}
and ap.monomer_id = #{monomerId}
and ap.area_id = #{areaId}
and ac.name like concat('%',#{name},'%')
and ap.serial_number like concat('%',#{serialNumber},'%')
and ap.specification like concat('%',#{specification},'%')
and ap.material like concat('%',#{material},'%')
and ap.use_property = #{useProperty}
